#[inductive(combiner_send)]
fn combiner_send_inductive(pre: Self, post: Self, response: Response, cur_slot: bool) {
    let j = pre.combiner.get_Responding_idx();

    // Show not_waiting_inv is preserved
    assert forall |i: nat| #[trigger] post.valid_idx(i) && post.clients.index(i).is_Idle() 
    implies !post.slots.index(i) by {
        if i == j {
            // The slot for client j is set to false in post
            assert(post.slots.index(i) == false);
        } else {
            // Other clients unchanged
            assert(pre.clients.index(i) == post.clients.index(i));
            assert(pre.slots.index(i) == post.slots.index(i));
            assert(pre.valid_idx(i) == post.valid_idx(i));

            // Since pre satisfies invariant
            if pre.valid_idx(i) && pre.clients.index(i).is_Idle() {
                assert(!pre.slots.index(i));
                assert(!post.slots.index(i));
            }
        }
    }

    // Show waiting_inv is preserved
    assert forall |i: nat| #[trigger] post.client_waiting(i) 
    implies post.request_stored(i) || post.response_stored(i) || post.combiner_has(i) by {
        // Client states are not changed by combiner_send
        // So if a client is waiting in post, it was waiting in pre
        assert(pre.client_waiting(i) == post.client_waiting(i));

        if i == j {
            // For client j, we know:
            // 1. pre.client_waiting(j) (from the deposit assertion)
            // 2. post.response_stored(j) (because we just deposited a response)
            // 3. post.request_stored(j) == pre.request_stored(j) (requests unchanged)
            // 4. post.combiner_has(j) == false (because idx was incremented)
            assert(post.response_stored(i));
        } else {
            // Other clients unchanged
            assert(pre.request_stored(i) == post.request_stored(i));
            assert(pre.response_stored(i) == post.response_stored(i));
            assert(pre.combiner_has(i) == post.combiner_has(i));
        }

        // Since pre satisfies invariant
        if pre.client_waiting(i) {
            assert(pre.request_stored(i) || pre.response_stored(i) || pre.combiner_has(i));
            // In post, we have:
            // - post.request_stored(i) == pre.request_stored(i) if i != j
            // - post.response_stored(i) == true if i == j (and possibly if i != j and it was true before)
            // - post.combiner_has(i) == false if i == j, == pre.combiner_has(i) if i != j
            // So one of the three conditions must still hold
            assert(post.request_stored(i) || post.response_stored(i) || post.combiner_has(i));
        }
    }

    // Show request_stored_inv is preserved (unchanged)
    assert forall |i: nat| #[trigger] post.request_stored(i) 
    implies post.client_waiting(i)
        && post.requests.index(i).rid == post.clients.index(i).get_Waiting_rid()
        && post.slots.index(i) by {
        // Requests are not changed by combiner_send
        assert(pre.request_stored(i) == post.request_stored(i));
        if pre.request_stored(i) {
            assert(pre.requests.index(i) == post.requests.index(i));
            assert(pre.clients.index(i) == post.clients.index(i));
            assert(pre.slots.index(i) == post.slots.index(i));
            assert(pre.valid_idx(i) == post.valid_idx(i));

            // Since pre satisfies invariant
            assert(pre.client_waiting(i));
            assert(pre.requests.index(i).rid == pre.clients.index(i).get_Waiting_rid());
            assert(pre.slots.index(i));

            assert(post.client_waiting(i));
            assert(post.requests.index(i).rid == post.clients.index(i).get_Waiting_rid());
            assert(post.slots.index(i));
        }
    }

    // Show response_stored_inv is preserved
    assert forall |i: nat| #[trigger] post.response_stored(i) 
    implies post.client_waiting(i)
        && post.responses.index(i).rid == post.clients.index(i).get_Waiting_rid()
