#[inductive(combiner_send)]
fn combiner_send_inductive(pre: Self, post: Self, response: Response, cur_slot: bool) {
    let j = pre.combiner.get_Responding_idx();

    // Show not_waiting_inv is preserved
    assert forall |i: nat| #[trigger] post.valid_idx(i) && post.clients.index(i).is_Idle() 
    implies !post.slots.index(i) by {
        if i == j {
            // The slot for client j is set to false in post
            assert(post.slots.index(i) == false);
        } else {
            // Other clients unchanged
            assert(pre.clients.index(i) == post.clients.index(i));
            assert(pre.slots.index(i) == post.slots.index(i));
            assert(pre.valid_idx(i) == post.valid_idx(i));

            // Since pre satisfies invariant
            if pre.valid_idx(i) && pre.clients.index(i).is_Idle() {
                assert(!pre.slots.index(i));
                assert(!post.slots.index(i));
            }
        }
    }

    // Show waiting_inv is preserved
    assert forall |i: nat| #[trigger] post.client_waiting(i) 
    implies post.request_stored(i) || post.response_stored(i) || post.combiner_has(i) by {
        // Client states are not changed by combiner_send
        // So if a client is waiting in post, it was waiting in pre
        assert(pre.client_waiting(i) == post.client_waiting(i));

        // Since pre satisfies invariant
        if pre.client_waiting(i) {
            assert(pre.request_stored(i) || pre.response_stored(i) || pre.combiner_has(i));
            // In post:
            // - If i != j: everything same as pre, so same disjunction holds
            // - If i == j: 
            //   * post.request_stored(j) == pre.request_stored(j)
            //   * post.response_stored(j) == true (we just deposited one)
            //   * post.combiner_has(j) == false (idx incremented past j)
            //   So the disjunction still holds because post.response_stored(j) is true
            assert(post.request_stored(i) || post.response_stored(i) || post.combiner_has(i));
        }
    }

    // Show request_stored_inv is preserved (unchanged)
    assert forall |i: nat| #[trigger] post.request_stored(i) 
    implies post.client_waiting(i)
        && post.requests.index(i).rid == post.clients.index(i).get_Waiting_rid()
        && post.slots.index(i) by {
        // Requests are not changed by combiner_send
        assert(pre.request_stored(i));
        assert(pre.requests.index(i) == post.requests.index(i));
        assert(pre.clients.index(i) == post.clients.index(i));
        assert(pre.slots.index(i) == post.slots.index(i));
        assert(pre.valid_idx(i) == post.valid_idx(i));

        // Since pre satisfies invariant
        assert(pre.client_waiting(i));
        assert(pre.requests.index(i).rid == pre.clients.index(i).get_Waiting_rid());
        assert(pre.slots.index(i));

        assert(post.client_waiting(i));
        assert(post.requests.index(i).rid == post.clients.index(i).get_Waiting_rid());
        assert(post.slots.index(i));
    }

    // Show response_stored_inv is preserved
    assert forall |i: nat| #[trigger] post.response_stored(i) 
    implies post.client_waiting(i)
        && post.responses.index(i).rid == post.clients.index(i).get_Waiting_rid()
        && !post.slots.index(i) by {
        if i == j {
            // This is the newly stored response for client j
            // Client j was waiting in pre (established by deposit assertion)
            assert(pre.client_waiting(i));
            // Client state unchanged
            assert(post.client_waiting(i));
            // The response has the right rid (established by precondition)
            assert(post.responses.index(i).rid == response.rid);
            // Show that response.rid == post.clients.index(i).get_Waiting_rid()
            // From the precondition: response_opt == Option::Some(response.rid)
            // And response_opt = pre.combiner.get_Responding_elems().index(j as int)
            // And from combiner_has_inv in pre: 
            // pre.combiner_has(j) ==> pre.combiner_rid(j) == pre.clients.index(j).get_Waiting_rid()
            // And pre.combiner_rid(j) = pre.combiner.get_Responding_elems().index(j as int).get_Some_0()
            // And response_opt = Option::Some(response.rid) = pre.combiner.get_Responding_elems().index(j as int)
            // So response.rid = pre.combiner.get_Responding_elems().index(j as int).get_Some_0() = pre.combiner_rid(j)
            // And from combiner_has_inv: pre.combiner_rid(j) == pre.clients.index(j).get_Waiting_rid()
            // Therefore response.rid == pre.clients.index(j).get_Waiting_rid() == post.clients.index(i).get_Waiting_rid()
            assert(response.rid == post.clients.index(i).get_Waiting_rid());
            // Slot is set to false
            assert(!post.slots.index(i));
        } else {
            // Other stored responses unchanged
            assert(pre.response_stored(i));
            assert(pre.responses.index(i) == post.responses.index(i));
            assert(pre.clients.index(i) == post.clients.index(i));
            assert(pre.slots.index(i) == post.slots.index(i));
            assert(pre.valid_idx(i) == post.valid_idx(i));

            // Since pre satisfies invariant
            assert(pre.client_waiting(i));
            assert(pre.responses.index(i).rid == pre.clients.index(i).get_Waiting_rid());
            assert(!pre.slots.index(i));

            assert(post.client_waiting(i));
            assert(post.responses.index(i).rid == post.clients.index(i).get_Waiting_rid());
            assert(!post.slots.index(i));
        }
    }

    // Show combiner_has_inv is preserved
    assert forall |i: nat| #[trigger] post.combiner_has(i) 
    implies post.client_waiting(i)
        && post.slots.index(i)
        && post.combiner_rid(i) == post.clients.index(i).get_Waiting_rid()
        && !post.request_stored(i) by {
        if i == j {
            // This element was just processed (idx incremented)
            // So it shouldn't be in combiner anymore
            assert(!post.combiner_has(i));
            // This case is impossible because we assumed post.combiner_has(i)
            assert(false);
        } else {
            // Other combiner elements unchanged
            assert(pre.combiner_has(i));
            assert(pre.combiner_rid(i) == post.combiner_rid(i));
            assert(pre.clients.index(i) == post.clients.index(i));
            assert(pre.slots.index(i) == post.slots.index(i));
            assert(pre.valid_idx(i) == post.valid_idx(i));
            assert(pre.request_stored(i) == post.request_stored(i));

            // Since pre satisfies invariant
            assert(pre.client_waiting(i));
            assert(pre.slots.index(i));
            assert(pre.combiner_rid(i) == pre.clients.index(i).get_Waiting_rid());
            assert(!pre.request_stored(i));

            assert(post.client_waiting(i));
            assert(post.slots.index(i));
            assert(post.combiner_rid(i) == post.clients.index(i).get_Waiting_rid());
            assert(!post.request_stored(i));
        }
    }
}

