// Show combiner_has_inv is preserved
assert forall |i: nat| #[trigger] post.combiner_has(i) 
implies post.client_waiting(i)
    && post.slots.index(i)
    && post.combiner_rid(i) == post.clients.index(i).get_Waiting_rid()
    && !post.request_stored(i) by {
    // In combiner_send, the idx is incremented, so elements at positions >= idx in pre
    // become elements at positions >= (idx+1) in post
    // If post.combiner_has(i), then i >= post.idx and post.elems[i].is_Some()
    // where post.idx = pre.idx + 1
    // This means i >= pre.idx + 1, so i > pre.idx, so if pre.combiner_has(i), it's because i >= pre.idx
    // But we need to be more careful

    // Actually, let's think about this correctly:
    // pre.combiner_has(i) means i >= pre.idx and pre.elems[i].is_Some()
    // post.combiner_has(i) means i >= post.idx and post.elems[i].is_Some()
    // where post.idx = pre.idx + 1 and post.elems = pre.elems
    // So post.combiner_has(i) iff i >= pre.idx + 1 and pre.elems[i].is_Some()
    // This implies i >= pre.idx and pre.elems[i].is_Some(), which is pre.combiner_has(i)
    // So post.combiner_has(i) implies pre.combiner_has(i)

    assert(post.combiner.get_Responding_idx() == pre.combiner.get_Responding_idx() + 1);
    assert(pre.combiner.get_Responding_elems() == post.combiner.get_Responding_elems());
    assert(post.combiner_has(i) ==> pre.combiner_has(i));

    // Values are unchanged
    assert(pre.combiner_rid(i) == post.combiner_rid(i));
    assert(pre.clients.index(i) == post.clients.index(i));
    // Slots can change for client j
    // assert(pre.slots.index(i) == post.slots.index(i));  // FALSE for i==j
    assert(pre.valid_idx(i) == post.valid_idx(i));
    assert(pre.request_stored(i) == post.request_stored(i));

    // Since pre satisfies invariant
    if pre.combiner_has(i) {
        assert(pre.client_waiting(i));
        assert(pre.slots.index(i));
        assert(pre.combiner_rid(i) == pre.clients.index(i).get_Waiting_rid());
        assert(!pre.request_stored(i));

        // If post.combiner_has(i), then pre.combiner_has(i), so all the above applies
        if post.combiner_has(i) {
            assert(post.client_waiting(i));
            // For slots, we need to be careful:
            if i == j {
                // Slot for client j was changed from cur_slot to false
                // But if post.combiner_has(j), that means j >= post.idx = pre.idx + 1
                // And pre.combiner_has(j) means j >= pre.idx
                // The deposit assertion in the transition says assert(pre.combiner_has(j))
                // So we know pre.combiner_has(j) is true, which means pre.slots.index(j) is true
                // But post.slots.index(j) is false
                // This would contradict the invariant unless post.combiner_has(j) is false

                // Wait, this suggests that post.combiner_has(j) should be false
                // But we're in a forall where we assume post.combiner_has(i)
                // So we can't have i == j
                assert(i != j);
                assert(pre.slots.index(i) == post.slots.index(i));
            } else {
                assert(pre.slots.index(i) == post.slots.index(i));
            }
            assert(post.combiner_rid(i) == post.clients.index(i).get_Waiting_rid());
            assert(!post.request_stored(i));
        }
    }
}

