        #[inductive(combiner_send_skip)]
        fn combiner_send_skip_inductive(pre: Self, post: Self) {
            let j = pre.combiner.get_Responding_idx();

            // Show not_waiting_inv is preserved
            assert forall |i: nat| #[trigger] post.valid_idx(i) && post.clients.index(i).is_Idle() 
            implies !post.slots.index(i) by {
                // All clients unchanged
                assert(pre.clients.index(i) == post.clients.index(i));
                assert(pre.slots.index(i) == post.slots.index(i));
                assert(pre.valid_idx(i) == post.valid_idx(i));

                // Since pre satisfies invariant
                if pre.valid_idx(i) && pre.clients.index(i).is_Idle() {
                    assert(!pre.slots.index(i));
                    assert(!post.slots.index(i));
                }
            }

            // Show waiting_inv is preserved
            assert forall |i: nat| #[trigger] post.client_waiting(i) 
            implies post.request_stored(i) || post.response_stored(i) || post.combiner_has(i) by {
                // All client states unchanged
                assert(pre.client_waiting(i) == post.client_waiting(i));
                assert(pre.request_stored(i) == post.request_stored(i));
                assert(pre.response_stored(i) == post.response_stored(i));

                // For combiner_has:
                // pre.combiner_has(i) means i >= pre.idx && pre.elems[i].is_Some()
                // post.combiner_has(i) means i >= post.idx && post.elems[i].is_Some()
                // where post.idx = pre.idx + 1 and post.elems = pre.elems
                // So post.combiner_has(i) iff i >= pre.idx + 1 && pre.elems[i].is_Some()
                // This implies i >= pre.idx && pre.elems[i].is_Some(), which is pre.combiner_has(i)
                // So post.combiner_has(i) implies pre.combiner_has(i)
                assert(post.combiner_has(i) ==> pre.combiner_has(i));

                // Since pre satisfies invariant
                if pre.client_waiting(i) {
                    assert(pre.request_stored(i) || pre.response_stored(i) || pre.combiner_has(i));
                    // In post:
                    // - request_stored(i) unchanged
                    // - response_stored(i) unchanged  
                    // - combiner_has(i): post.combiner_has(i) implies pre.combiner_has(i)
                    // If pre.combiner_has(i) and i >= pre.idx + 1, then post.combiner_has(i)
                    // If pre.combiner_has(i) and i = pre.idx, then !post.combiner_has(i)
                    // In the latter case (i = j), we still need to show post.request_stored(i) || post.response_stored(i)
                    // But since i = j and response_opt = Option::None for client j in combiner_send_skip,
                    // pre.combiner_has(j) should be false (since combiner_has(j) means elems[j].is_Some())
                    // So pre.combiner_has(j) is false, which means one of pre.request_stored(j) or pre.response_stored(j) is true
                    // Since requests and responses are unchanged for i != j, and combiner_send_skip doesn't deposit responses,
                    // we have post.request_stored(j) = pre.request_stored(j) and post.response_stored(j) = pre.response_stored(j)
                    // Therefore, the disjunction holds
                    assert(post.request_stored(i) || post.response_stored(i) || post.combiner_has(i));
